/* ===================== BÀI 10 · Địa chỉ hiệu dụng hợp lệ ===================== */
/* Bài 10 · Địa chỉ hiệu dụng hợp lệ (AMTS-EMB-002-M03-L02, X86-010) — sinh bởi tools/author/mpu8086/l10.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P10=[{"label": "Ví dụ: cơ sở, chỉ số, độ dời trên một bảng", "code": "; Ví dụ 1: cơ sở, chỉ số, độ dời trên cùng một bảng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      4 DUP(?)                ; độ lệch 0000h…0003h\nbang    DB      10H, 20H, 30H, 40H, 50H ; từ 0004h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET bang         ; cơ sở BX = 0004h\n        MOV     SI, 3                   ; chỉ số SI = 3\n        MOV     AL, [BX]                ; EA = 0004h → 10h\n        MOV     kq, AL\n        MOV     AL, [BX+SI]             ; EA = 0007h → 40h\n        MOV     kq+1, AL\n        MOV     AL, [BX+SI+1]           ; EA = 0008h → 50h\n        MOV     kq+2, AL\n        MOV     AL, bang[SI]            ; EA = 0004h + 3 → 40h\n        MOV     kq+3, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước. Ở mỗi lệnh đọc, hình địa chỉ vật lý của phần Thanh ghi ghi rõ cách tính EA: [BX] = 0004h, [BX+SI] = 0007h, [BX+SI+độ dời] = 0008h, bang[SI] = 0004h + 3. Cột chu kỳ: 13, 15, 19, 17 (8 + EA 5, 7, 11, 9). Đoán trước: sau MOV AL, [BX+SI+1], AL bằng bao nhiêu? Đáp án 50h."}, {"label": "Ví dụ: độ dời âm, dương và EA quay vòng", "code": "; Ví dụ 2: độ dời âm, dương và EA quay vòng 64 KB\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?                       ; 0000h\nkq2     DB      ?                       ; 0002h\nday     DB      1, 2, 3, 4, 5           ; 0003h…0007h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET day+2        ; BX = 0005h (phần tử 3)\n        MOV     AL, [BX-1]              ; độ dời −1: byte FFh\n        MOV     AH, [BX+1]              ; độ dời +1: byte 01h\n        MOV     kq, AX                  ; kq = 0402h\n        MOV     SI, -1                  ; SI = FFFFh\n        MOV     DL, [BX+SI]             ; EA = (0005h + FFFFh) mod 10000h\n        MOV     kq2, DL                 ; = 0004h → 2\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "MOV AL, [BX-1] có mã 8A 47 FF: độ dời 8 bit FFh = −1. SI = FFFFh nên [BX+SI] = 0005h + FFFFh = 1 0004h, giữ 16 bit thấp: EA = 0004h. Xem kq = 02 04 và kq2 = 02 ở phần Bộ nhớ. Đoán trước: sau MOV AH, [BX+1], AX bằng bao nhiêu? Đáp án 0402h."}, {"label": "Lỗi: [AX] không phải địa chỉ hợp lệ", "code": "; Lỗi: AX không dùng làm thanh ghi địa chỉ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DB      10H, 20H, 30H\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, OFFSET bang\n        MOV     DL, [AX]                ; LỖI: chỉ BX, BP, SI, DI\n; Sửa: MOV BX, AX rồi MOV DL, [BX]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch có chủ đích: AX không có mặt trong bảng r/m nên không có mã máy cho [AX]. Sửa: chép địa chỉ sang BX (hoặc SI, DI) rồi dùng [BX]."}, {"label": "Lỗi: SI và DI cùng trong một địa chỉ", "code": "; Lỗi: hai thanh ghi chỉ số SI và DI cùng lúc\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      1, 2, 3\ndich    DB      3 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET nguon\n        MOV     DI, 1\n        MOV     AL, [SI+DI]             ; LỖI: SI + DI không có trên 8086\n; Sửa: MOV BX, OFFSET nguon rồi MOV AL, [BX+DI]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch có chủ đích: một địa chỉ chỉ có tối đa một thanh ghi chỉ số. Sửa: dùng BX làm cơ sở: MOV BX, OFFSET nguon rồi MOV AL, [BX+DI] (r/m 001)."}, {"label": "Ví dụ: duyệt mảng word bằng [BX+SI]", "code": "; Ví dụ 5: duyệt mảng word bằng [BX+SI], SI tăng 2\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      100, 200, 300, 400\ntong    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET mang         ; cơ sở: đầu mảng\n        MOV     SI, 0                   ; chỉ số tính bằng byte\n        MOV     AX, 0\n        MOV     CX, 4\ncong:\n        ADD     AX, [BX+SI]             ; 9 + EA 7 = 16 chu kỳ\n        ADD     SI, 2                   ; mỗi phần tử word dài 2 byte\n        LOOP    cong\n        MOV     tong, AX                ; 1000 = 03E8h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "SI là chỉ số tính bằng byte nên tăng 2 cho mỗi word. Mỗi vòng: ADD AX, [BX+SI] 16 chu kỳ (9 + EA 7), ADD SI, 2 là 4, LOOP 17 (vòng cuối 5). Đoán trước: ở vòng thứ 3, EA của [BX+SI] bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: SI tăng 1 trong mảng word", "code": "; Lỗi: SI tăng 1 trong mảng word\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      100, 200, 300, 400\ntong    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET mang\n        MOV     SI, 0\n        MOV     AX, 0\n        MOV     CX, 4\ncong:\n        ADD     AX, [BX+SI]             ; SI = 1, 3: đọc lệch nửa word\n        INC     SI                      ; LỖI: phải tăng 2\n        LOOP    cong\n        MOV     tong, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic có chủ đích: SI tăng 1 nên vòng 2 đọc word ở độ lệch 1 (byte 00h, C8h → C800h), vòng 4 đọc 2C00h; tong = F52Ch thay vì 03E8h. Hai lần đọc ở địa chỉ lẻ tốn 20 chu kỳ thay vì 16. Sửa: ADD SI, 2 như Ví dụ 5. Đoán trước: sau vòng 2, AX bằng bao nhiêu? Đáp án C864h."}, {"label": "Ví dụ: cùng phép cộng, hai chi phí EA", "code": "; Ví dụ 7: cùng phép cộng, hai dạng địa chỉ, hai chi phí\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntongA   DW      ?\ntongB   DW      ?\nmang    DW      100, 200, 300, 400      ; từ 0004h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0                   ; Cách A: tên mảng + SI\n        MOV     SI, 0\n        MOV     CX, 4\nlapA:\n        ADD     AX, mang[SI]            ; độ dời 16 bit + SI: EA 9\n        ADD     SI, 2\n        LOOP    lapA\n        MOV     tongA, AX\n        MOV     DX, 0                   ; Cách B: con trỏ SI\n        MOV     SI, OFFSET mang\n        MOV     CX, 4\nlapB:\n        ADD     DX, [SI]                ; chỉ SI: EA 5\n        ADD     SI, 2\n        LOOP    lapB\n        MOV     tongB, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai vòng cộng cùng mảng. So cột chu kỳ: ADD AX, mang[SI] tốn 18 (EA 9, 4 byte), ADD DX, [SI] tốn 14 (EA 5, 2 byte). Cả vòng: 144 so với 128 chu kỳ. Đoán trước: ở cách B, trước vòng lặp SI bằng bao nhiêu? Đáp án 0004h (OFFSET mang)."}];
