makeX86Ex(document.getElementById("ex-l10"),sim10,[{"t": "Ký tự thứ k", "d": "Biến chuoi DB 'AMTS8086' có 8 ký tự, đánh số từ 0. Đọc một phím chữ số k (0–7) bằng INT 21h hàm 08h rồi in ký tự chuoi[k] bằng INT 21h hàm 02h. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: in ký tự thứ k của chuỗi (k = 0…7)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'AMTS8086'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc phím chữ số k\n        INT     21H\n; Viết code ở đây: in ký tự chuoi[k]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "out": "A"}, {"in": "7", "out": "6"}, {"in": "3", "out": "S"}, {"in": "4", "out": "8"}, {"in": "5", "out": "0"}, {"in": "1", "out": "M"}]}, {"t": "Cặp ký tự đối xứng", "d": "Biến chuoi DB 'ABCDEFGH' (chỉ số 0–7). Code mẫu đã đặt BX = OFFSET chuoi. Đọc một phím chữ số k (0–7), in chuoi[k] rồi in chuoi[7 − k], liền nhau trên một dòng. Dùng hai địa chỉ dạng cơ sở + chỉ số: [BX+SI] và [BX+DI]. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: in chuoi[k] rồi chuoi[7 - k]\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'ABCDEFGH'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET chuoi        ; cơ sở\n        MOV     AH, 08H                 ; đọc phím chữ số k\n        INT     21H\n; Viết code ở đây\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "out": "AH"}, {"in": "7", "out": "HA"}, {"in": "3", "out": "DE"}, {"in": "4", "out": "ED"}, {"in": "1", "out": "BG"}, {"in": "6", "out": "GB"}]}, {"t": "Tổng n word nhanh hơn", "d": "Mảng mang có 8 word 1000, 2000, …, 8000. Đọc một phím chữ số n (1–8) và ghi tổng n phần tử đầu vào biến word tong. Code mẫu cho kết quả đúng nhưng mỗi vòng dùng địa chỉ có độ dời 16 bit và cộng thẳng vào ô nhớ. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: tổng n phần tử word đầu tiên\n; Bản này đúng nhưng chậm: mỗi vòng đọc mảng bằng độ dời\n; 16 bit + BX rồi cộng thẳng vào ô nhớ tong. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?\nmang    DW      1000, 2000, 3000, 4000\n        DW      5000, 6000, 7000, 8000\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc n (1…8)\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     CX, AX                  ; CX = n\n        MOV     tong, 0\n        MOV     BX, 0\ncong:\n        MOV     AX, mang[BX]\n        ADD     tong, AX\n        ADD     BX, 2\n        LOOP    cong\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "8", "mem": [{"at": "tong", "bytes": [160, 140]}]}, {"in": "1", "mem": [{"at": "tong", "bytes": [232, 3]}]}, {"in": "3", "mem": [{"at": "tong", "bytes": [112, 23]}]}, {"in": "5", "mem": [{"at": "tong", "bytes": [152, 58]}]}, {"in": "2", "mem": [{"at": "tong", "bytes": [184, 11]}]}, {"in": "7", "mem": [{"at": "tong", "bytes": [96, 109]}]}], "perf": {"cycles": 425, "bytes": 40}}]);

makeQuiz("quiz10","score10",[{"q": "Dạng địa chỉ nào <b>không<\/b> hợp lệ trên 8086?", "o": ["<code>[BP+SI]<\/code>", "<code>[SI+DI]<\/code>", "<code>[BX+DI+5]<\/code>", "<code>[BP]<\/code>"], "a": 1, "e": "Một EA có tối đa một thanh ghi cơ sở (BX, BP) và một thanh ghi chỉ số (SI, DI); SI và DI đều là chỉ số. [BP] hợp lệ (được dịch thành [BP+0])."}, {"q": "BX = 0010h, SI = 0004h. Bảng ở DS:0010h chứa 11h, 22h, 33h, 44h, 55h, 66h. Sau lệnh sau, AL bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AL, [BX+SI+1]<\/pre>", "o": ["55h, vì độ dời +1 bị bỏ qua khi có SI", "22h, vì SI chỉ đếm phần tử từ 1", "66h, vì EA = 0010h + 4 + 1 = 0015h", "11h, vì AL chỉ đọc theo BX"], "a": 2, "e": "EA = BX + SI + 1 = 0015h, là byte thứ 6 của bảng (66h). Độ dời được cộng như mọi phần khác của công thức."}, {"q": "Vì sao <code>MOV AL, [BP]<\/code> dịch thành 3 byte <code>8A 46 00<\/code> còn <code>MOV AL, [BX]<\/code> chỉ 2 byte?", "o": ["Ô mod 00, r/m 110 dành cho địa chỉ trực tiếp nên [BP] phải mã hóa thành [BP+0]", "BP dùng đoạn SS nên lệnh luôn phải có thêm một byte tiền tố đoạn", "BP là thanh ghi con trỏ ngăn xếp nên cần độ dời để chỉ đỉnh", "Trình dịch luôn thêm độ dời 0 cho mọi thanh ghi cơ sở"], "a": 0, "e": "Trong bảng ModR/M, mod 00 r/m 110 nghĩa là địa chỉ trực tiếp 16 bit, nên [BP] không có dạng không độ dời: dùng mod 01 với d8 = 00. Byte 46h ở đây là ModR/M, không phải tiền tố; [BX] (r/m 111, mod 00) không cần độ dời."}, {"q": "BX = 0003h, SI = FFFFh. EA của <code>[BX+SI]<\/code> là bao nhiêu?", "o": ["10002h, vì 8086 có 20 đường địa chỉ", "FFFCh, vì SI được trừ đi BX", "Không tính được: CPU báo lỗi tràn địa chỉ", "0002h, vì phép cộng EA chỉ giữ 16 bit"], "a": 3, "e": "EA là số 16 bit: 0003h + FFFFh = 1 0002h, bỏ bit thứ 17 còn 0002h; không có lỗi. 20 bit chỉ xuất hiện khi ghép với thanh ghi đoạn (Ví dụ 2)."}, {"q": "Vòng lặp duyệt mảng word cần một lệnh đọc mỗi vòng. Lệnh nào có thời gian EA nhỏ nhất?", "o": ["<code>ADD AX, mang[SI]<\/code> với SI bắt đầu từ 0", "<code>ADD AX, [SI]<\/code> với SI đã nạp OFFSET mang", "<code>ADD AX, [BX+SI]<\/code> với BX = OFFSET mang", "<code>ADD AX, mang[BX+SI]<\/code> với BX = 0"], "a": 1, "e": "EA: [SI] 5; [BX+SI] 7; mang[SI] (thanh ghi + độ dời) 9; mang[BX+SI] 11. Nạp OFFSET vào con trỏ trước vòng lặp cho dạng rẻ nhất (Ví dụ 7, bài tập 3)."}]);

